void URLRequest::Start() {
  DCHECK(delegate_);

  switch (isolation_info_.GetNetworkIsolationPartition()) {
    case NetworkIsolationPartition::kGeneral:
      break;
    case NetworkIsolationPartition::kSharedWorkerSameSiteCookiesNone:
      // This partition is only used for SharedWorkers with SameSite=None cookie
      // restrictions, so SiteForCookies must be null when credentials are
      // allowed.
      CHECK(!allow_credentials() ||
            (isolation_info_.site_for_cookies().IsNull() &&
             site_for_cookies_.IsNull()));
      break;
    case NetworkIsolationPartition::kFedCmUncredentialedRequests:
    case NetworkIsolationPartition::kDnsOverHttps:
      // Credentials are not supported with these non-general
      // NetworkIsolationPartitions.
      CHECK(!allow_credentials());
      break;
  }

  if (status_ != OK) {
    return;
  }

  if (context_->require_network_anonymization_key()) {
    DCHECK(!isolation_info_.IsEmpty() ||
           NetworkIsolationPartitionAlwaysAllowEmptyPartition(
               isolation_info_.GetNetworkIsolationPartition()));
  }

  // Some values can be NULL, but the job factory must not be.
  DCHECK(context_->job_factory());

  // Anything that sets |blocked_by_| before start should have cleaned up after
  // itself.
  DCHECK(blocked_by_.empty());

  g_url_requests_started = true;
  response_info_.request_time = base::Time::Now();

  load_timing_info_ = LoadTimingInfo();
  load_timing_info_.request_start_time = response_info_.request_time;
  load_timing_info_.request_start = base::TimeTicks::Now();

  if (network_delegate()) {
    OnCallToDelegate(NetLogEventType::NETWORK_DELEGATE_BEFORE_URL_REQUEST);
    int error = network_delegate()->NotifyBeforeURLRequest(
        this,
        base::BindOnce(&URLRequest::BeforeRequestComplete,
                       base::Unretained(this)),
        &delegate_redirect_url_);
    // If ERR_IO_PENDING is returned, the delegate will invoke
    // |BeforeRequestComplete| later.
    if (error != ERR_IO_PENDING)
      BeforeRequestComplete(error);
    return;
  }

  StartJob(context_->job_factory()->CreateJob(this));
}

