    root = ET.fromstring(result.stdout)
    replacements = list(root.findall('replacement'))
    print(json.dumps({'file': path, 'format_replacements': len(replacements), 'incomplete_format': root.get('incomplete_format')}))
    for item in replacements:
        print(json.dumps({'offset': item.get('offset'), 'length': item.get('length'), 'replacement': item.text}))
