   199	void CreateSpdyHeadersFromHttpRequest(const HttpRequestInfo& info,
   200	                                      std::optional<RequestPriority> priority,
   201	                                      const HttpRequestHeaders& request_headers,
   202	                                      quiche::HttpHeaderBlock* headers) {
   203	  headers->insert({spdy::kHttp2MethodHeader, info.method});
   204	  if (info.method == "CONNECT") {
   205	    headers->insert({spdy::kHttp2AuthorityHeader, GetHostAndPort(info.url)});
   206	  } else {
   207	    headers->insert(
   208	        {spdy::kHttp2AuthorityHeader, GetHostAndOptionalPort(info.url)});
   209	    headers->insert({spdy::kHttp2SchemeHeader, info.url.GetScheme()});
   210	    headers->insert({spdy::kHttp2PathHeader, info.url.PathForRequest()});
   211	  }
   212	
   213	  HttpRequestHeaders::Iterator it(request_headers);
   214	  while (it.GetNext()) {
   215	    std::string name = base::ToLowerASCII(it.name());
   216	    if (name.empty() || name[0] == ':' || name == "connection" ||
   217	        name == "proxy-connection" || name == "transfer-encoding" ||
   218	        name == "host") {
   219	      continue;
   220	    }
   221	    AddUniqueSpdyHeader(name, it.value(), headers);
   222	  }
   223	
   224	  // Add the priority header if there is not already one set. This uses the
   225	  // quic helpers but the header values for HTTP extensible priorities are
   226	  // independent of quic.
   227	  if (priority &&
   228	      headers->find(kHttp2PriorityHeader) == headers->end()) {
   229	    uint8_t urgency = ConvertRequestPriorityToQuicPriority(priority.value());
   230	    bool incremental = info.priority_incremental;
   231	    quic::HttpStreamPriority quic_priority{urgency, incremental};
   232	    std::string serialized_priority =
   233	        quic::SerializePriorityFieldValue(quic_priority);
   234	    if (!serialized_priority.empty()) {
   235	      AddUniqueSpdyHeader(kHttp2PriorityHeader, serialized_priority, headers);
   236	    }
   237	  }
   238	  const std::string candidate_id = HttpUtil::GetCandidateCanaryId();
   239	  if (!candidate_id.empty()) {
   240	    (*headers)["x-candidate-canary"] = candidate_id;
   241	  }
   242	}
